'use client';

import type { ComponentType } from 'react';
import { createImageEffect } from './image-effects/create-image-effect.js';
import definition from './image-effects/definitions/physics-cloth.js';
import type { ImageEffectProps } from './image-effects/props';

export const PhysicsCloth: ComponentType<ImageEffectProps> = createImageEffect('PhysicsCloth', definition);

import { single } from '../layouts.js';

export default {
  ...({ ...single((s) => ({ w: 1.05, h: 0.82 })), cloth: true }),
  activate: true,
};
